        public LanguageService()
        {
            _currentLanguage = LoadSavedLanguage();
        }

        public string GetText(string key)
        {
            if (Translations.TryGetValue(_currentLanguage, out var dict) && dict.TryGetValue(key, out var val))
                return val;
            // Fallback to English
            if (Translations.TryGetValue("English", out var enDict) && enDict.TryGetValue(key, out var enVal))
                return enVal;
            return key;
        }

        public void SetLanguage(string language)
        {
            if (_currentLanguage == language) return;
            _currentLanguage = language;
            SaveLanguage(language);
            OnLanguageChanged?.Invoke();
        }

        protected virtual string LoadSavedLanguage() => "English";
        protected virtual void SaveLanguage(string language) { }
    }
}
